def transform(grid):
    """Fill each zero-valued cavity with its number of zeros, modulo 10."""
    h, w = len(grid), len(grid[0])
    exterior = [[False] * w for _ in range(h)]
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
